INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29101, 'Hebrews 12:22', 'Hebrews', 12, 22, '&nbsp;خو تاسو د صيون غر د ژوندى خُدائ پاک ښار آسمانى يروشلم او د بې‌شمېره او د زرګونو فرښتو محفل ته راغلى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29102, 'Hebrews 12:23', 'Hebrews', 12, 23, '&nbsp;او تاسو د خُدائ پاک اول پېدا شوو مجلس ته راغلى يئ د چا نومونه چې په آسمان کښې ليکلے شوى دى. تاسو خُدائ پاک له راغلى يئ چې د ټولو خلقو منصف دے، او تاسو د صادقانو روحونو ملاقات له راغلى يئ چې کامِل شوى دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29103, 'Hebrews 12:24', 'Hebrews', 12, 24, '&nbsp;او تاسو د نوې لوظ مينځګړى عيسىٰ او د هغۀ نوستلے شوې د شهادت وينې له راغلى يئ، او د هغۀ قربانى د هابيل د قربانۍ نه ډېر بهتره وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29104, 'Hebrews 12:25', 'Hebrews', 12, 25, '&nbsp;نو پس خبردار شئ چې د هغۀ نه اِنکار ونۀ کړئ څوک چې تاسو ته کلام کوى. نو بيا هغه خلقو ته چې د خُدائ پاک کلام په زمکه اورولے شو، چې هغوئ رد کړو نو بچ نۀ شول، نو هغه پېغام چې د آسمان نه اورولے کيږى کۀ د هغۀ نه مخ اړوُو نو څنګه به بچ شُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29105, 'Hebrews 12:26', 'Hebrews', 12, 26, '&nbsp;د خُدائ پاک آواز هغه وخت زمکه ولړزوله خو اوس هغۀ دا لوظ کړے دے چې، ”اوس يو ځل بيا به زۀ يواځې زمکه نه، بلکې آسمان هم ولړزوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29106, 'Hebrews 12:27', 'Hebrews', 12, 27, '&nbsp;د هغۀ د ”يو ځل بيا“ الفاظ دې ته اِشاره کوى چې خوځېدونکى څيزونه به ختم شى، او نۀ خوځېدونکى څيزونه به پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29107, 'Hebrews 12:28', 'Hebrews', 12, 28, '&nbsp;نو چې مونږ ته داسې بادشاهى ملاوېدونکې ده چې هغه نۀ خوځېدونکې ده، نو راځئ چې شُکر ګزارى او په احترام او يرې سره خُدائ پاک ته خوښ عبادت وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29108, 'Hebrews 12:29', 'Hebrews', 12, 29, '&nbsp;نو ځکه چې زمونږ خُدائ پاک سوزونکے اور هم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29109, 'Hebrews 13:1', 'Hebrews', 13, 1, '&nbsp;د وروڼو او خوېندو په شان د يو بل سره مينه کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29110, 'Hebrews 13:2', 'Hebrews', 13, 2, '&nbsp;د مسافرو د مېلمستيا کولو نه بې‌پرواه کېږئ مه، ځکه چې د دې په وجه ځينو خلقو د فرښتو مېلمستيا هم کړې ده خو پوهه شوى نۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29111, 'Hebrews 13:3', 'Hebrews', 13, 3, '&nbsp;قېديان داسې يادوئ لکه چې تاسو ورسره په قېد کښې يئ، او چې د چا سره بد سلوکى کيږى، هغوئ داسې ګڼئ لکه چې تاسو سره په خپله بد سلوکى شوى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29112, 'Hebrews 13:4', 'Hebrews', 13, 4, '&nbsp;په کار دى چې ټول د وادۀ احترام وکړى، او ښځه او خاوند دې د يو بل سره وفادار پاتې شى ځکه چې خُدائ پاک به په خپله د حرامکارو زناکارو عدالت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29113, 'Hebrews 13:5', 'Hebrews', 13, 5, '&nbsp;د پېسو د مينې نه خپل ځان وساتئ او څۀ چې درسره دى په هغې صبر کوئ، ځکه چې خُدائ پاک فرمائيلى دى چې، ”زۀ به هيڅکله هم تاسو نۀ پرېږدم، او تاسو به هيڅکله نۀ هېروم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29114, 'Hebrews 13:6', 'Hebrews', 13, 6, '&nbsp;نو ځکه مونږ ډېر په زړۀ ورتيا سره وايو چې، ”مالِک زما مددګار دے، زۀ به ونۀ يرېږم، انسان به زما څۀ وکړى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29115, 'Hebrews 13:7', 'Hebrews', 13, 7, '&nbsp;خپل مشران ياد ساتئ، چا چې تاسو ته د خُدائ پاک کلام بيان کړو. د هغوئ د ژوند د طريقو نتيجو ته غور وکړئ او د هغوئ د ايمان سره سيالى کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29116, 'Hebrews 13:8', 'Hebrews', 13, 8, '&nbsp;عيسىٰ مسيح پرون، نن او تل تر تله يو شان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29117, 'Hebrews 13:9', 'Hebrews', 13, 9, '&nbsp;د هر قسم او مختلف تعليمونو په وجه بې‌لارې کېږئ مه، ځکه چې دا ښۀ ده چې زړۀ په فضل مضبوط شى، نۀ د هغه خوراکونو په اصُولو کومو چې هغوئ ته څۀ فائده نۀ ده ورکړى چا چې دا منل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29118, 'Hebrews 13:10', 'Hebrews', 13, 10, '&nbsp;زمونږ داسې قربان‌ګاه ده چې هغوئ ترې د خوراک کولو حق نۀ لرى څوک چې په خېمه کښې خدمت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29119, 'Hebrews 13:11', 'Hebrews', 13, 11, '&nbsp;مشر اِمام د ځناورو وينه زيات مقدس ځائ ته د ګناه د کفارې په طور وړى، خو د هغوئ لاشونه د خېمې نه بهر سوزولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29120, 'Hebrews 13:12', 'Hebrews', 13, 12, '&nbsp;نو ځکه عيسىٰ هم د ښار د دروازې نه بهر تکليف وزغملو د دې دپاره چې د خپلې وينې په وسيله خلق مقدس کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29121, 'Hebrews 13:13', 'Hebrews', 13, 13, '&nbsp;نو راځئ چې هغۀ له د خېمو نه بهر ورشُو او هغه بې‌عزتى وزغمو چې هغۀ زغملې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29122, 'Hebrews 13:14', 'Hebrews', 13, 14, '&nbsp;ځکه چې دلته زمونږ يو ښار قائم پاتې کېدونکے نشته بلکې مونږ د هغه ښار په لټون کښې يُو چې راتلونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29123, 'Hebrews 13:15', 'Hebrews', 13, 15, '&nbsp;ځکه دې د عيسىٰ په وسيله مونږ مسلسل خُدائ پاک ته د شُکر ګزارۍ قربانى پېش کوُو او دا د ذکر هغه مېوه ده چې د هغۀ د نوم اقرار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29124, 'Hebrews 13:16', 'Hebrews', 13, 16, '&nbsp;او نېکى کول او سخاوت مۀ هېروئ ځکه چې خُدائ پاک په داسې قربانو خوشحاليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29125, 'Hebrews 13:17', 'Hebrews', 13, 17, '&nbsp;د خپلو مشرانو خبره اورئ او د هغوئ د حُکم تابعدارى کوئ ځکه چې هغوئ ستاسو په روحانى ژوند نظر ساتى او خُدائ پاک به د هغوئ په خپله تپوس کوى، نو هغوئ دې خپله ذمه وارى په خوشحالۍ او بې‌شکايته سر ته رسوى، هسې نه چې تاسو ته د دې نه څۀ فائده مِلاو نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29126, 'Hebrews 13:18', 'Hebrews', 13, 18, '&nbsp;زمونږ دپاره دُعا کوئ ځکه چې زمونږ يقين دے چې زمونږ ضمير پاک دے او زمونږ خواهش دے چې په هر لحاظ د عزت ژوند تېر کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29127, 'Hebrews 13:19', 'Hebrews', 13, 19, '&nbsp;زۀ تاسو ته خاص درخواست کوم چې دُعا وکړئ نو چې زۀ زر تاسو له بيا راشم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29128, 'Hebrews 13:20', 'Hebrews', 13, 20, '&nbsp;اوس دې د سلامتۍ خُدائ پاک چا چې د تل د لوظ د وينې په وسيله زمونږ مالِک عيسىٰ چې لوئ شپون دے د مرګ نه بيا راژوندے کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29129, 'Hebrews 13:21', 'Hebrews', 13, 21, '&nbsp;هغه دې د خپلې رضا پوره کولو دپاره تاسو ته هر څۀ درکړى او هغه دې د عيسىٰ مسيح په وسيله مونږ کښې هغه کارونه وکړى څۀ چې د هغۀ خوښ وى. د هغۀ حمد و ثنا دې تل تر تله وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29130, 'Hebrews 13:22', 'Hebrews', 13, 22, '&nbsp;اے وروڼو او خوېندو، زۀ تاسو ته مِنت زارى کوم چې زما د نصيحت په کلام باندې غور وکړئ، کومه لنډه ليکنه چې ما تاسو ته وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29131, 'Hebrews 13:23', 'Hebrews', 13, 23, '&nbsp;زۀ غواړم چې تاسو خبر شئ چې زمونږ ورور تيموتيوس آزاد شو. کۀ چرې هغه دلته زر راشى نو زۀ به هغۀ سره تاسو له ملاقات له درشم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29132, 'Hebrews 13:24', 'Hebrews', 13, 24, '&nbsp;خپلو ټولو مشرانو او ټولو مقدسينو ته سلام ووايئ. د اِټلى ايمانداران وروڼه تاسو ته سلام کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29133, 'Hebrews 13:25', 'Hebrews', 13, 25, '&nbsp;او په تاسو ټولو دې فضل وى، آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29134, 'James 1:1', 'James', 1, 1, '&nbsp;د خُدائ پاک او د مالِک عيسىٰ مسيح غلام د يعقوب د طرفه دې هغه دولسو واړو قبيلو ته چې په مختلفو قومونو کښې خوارۀ وارۀ شوى دى، هغوئ ټولو ته دې سلام وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29135, 'James 1:2', 'James', 1, 2, '&nbsp;اے زما وروڼو او خوېندو، کله چې تاسو په قِسما قِسم آزمېښتونو کښې راګېر شئ نو خپل ځان بختور ګڼئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29136, 'James 1:3', 'James', 1, 3, '&nbsp;ځکه چې تاسو ته پته ده چې ستاسو د ايمان آزمېښت صبر پېدا کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29137, 'James 1:4', 'James', 1, 4, '&nbsp;نو پرېږدئ چې صبر په تاسو کښې خپل کار پوره کړى چې تاسو پاخۀ او بالغان شئ او په تاسو کښې به بلکل د څۀ خبرې کمے نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29138, 'James 1:5', 'James', 1, 5, '&nbsp;خو کۀ په تاسو کښې په چا کښې د حِکمت کمے وى نو هغه دې د خُدائ پاک نه وغواړى څوک چې بې‌خفګانه ټولو له په سخاوت سره ورکوى او تاسو له به يې هم درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29139, 'James 1:6', 'James', 1, 6, '&nbsp;خو په ايمان سره دې سوال کوى او هيڅ شک مۀ کوئ ځکه چې شک کوونکے د سمندر د هغه چپو په مِثال دے کومې چې د هوا په زور بره او ښکته کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29140, 'James 1:7', 'James', 1, 7, '&nbsp;داسې سړے دې دا نۀ ګڼى چې ګنې ما ته به د مالِک نه څۀ په لاس راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29141, 'James 1:8', 'James', 1, 8, '&nbsp;داسې سړے دوه زړيه وى او په خپلو ټولو کارونو ټينګ ولاړ نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29142, 'James 1:9', 'James', 1, 9, '&nbsp;نو غريب ورور دې په خپله اوچته مرتبه فخر وکړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29143, 'James 1:10', 'James', 1, 10, '&nbsp;خو مالدار دې په خپل عاجز حالت فخر وکړى، ځکه چې مالداره به لکه د ځنګلى ګل په شان اوچ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29144, 'James 1:11', 'James', 1, 11, '&nbsp;څنګه چې د نمر تاو واښۀ او ګلونه اوچوى او د هغوئ ښائست ختموى، نو دغه شان به مالدار هم سره د خپل ټول کاروبار ختم او د خاورو سره خاورې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29145, 'James 1:12', 'James', 1, 12, '&nbsp;بختور دے هغه څوک چې آزمېښت برداشت کړى، ځکه کله چې هغه په آزمېښت کښې قائم پاتې شى نو هغه به د ژوندون تاج حاصل کړى د کوم چې خُدائ پاک د خپلو مينه والو سره وعده کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29146, 'James 1:13', 'James', 1, 13, '&nbsp;د آزمېښت په وخت کښې دې څوک هم داسې نۀ وائى چې، ”زۀ خُدائ پاک ووآزمائيلم،“ ځکه چې خُدائ پاک څوک هم په ګناه نۀ آزمائى او نۀ هغه څوک په آزمېښت کښې اچوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29147, 'James 1:14', 'James', 1, 14, '&nbsp;خو هر څوک هغه وخت په آزمېښت کښې پرېوځى کله چې هغه د خپلو شهوانى خواهشاتو په جال کښې راګېر شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29148, 'James 1:15', 'James', 1, 15, '&nbsp;نو کله چې د هغۀ بد خواهش راوچت شى نو ګناه ترېنه پېدا شى، او کله چې ګناه زياته شى نو مرګ ترې پېدا شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29149, 'James 1:16', 'James', 1, 16, '&nbsp;اے زما خوږو وروڼو او خوېندو، مۀ دوکه کېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29150, 'James 1:17', 'James', 1, 17, '&nbsp;هر ښۀ او کامِل نعمت زمونږ د خُدائ پلار د طرف نه راځى چا چې په آسمان کښې نُور پېدا کړے دے. هغه کله هم نۀ بدليږى او نۀ تيارۀ رالېږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29151, 'James 1:18', 'James', 1, 18, '&nbsp;هغۀ د خپل مقصد پوره کولو دپاره مونږ د حق کلام په وسيله پېدا کړُو نو چې مونږ د هغۀ په مخلوقاتو کښې وړومبۍ مېوه شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29152, 'James 1:19', 'James', 1, 19, '&nbsp;اے زما وروڼو او خوېندو، دا خبره ياده ساتئ چې هر څوک دې په اورېدو کښې تېز او په وينا کښې قلاره او په غصه کښې سوړ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29153, 'James 1:20', 'James', 1, 20, '&nbsp;ځکه چې د انسان غصه د خُدائ پاک د صداقت کار نۀ شى کاملولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29154, 'James 1:21', 'James', 1, 21, '&nbsp;نو ځکه تاسو ټول د ځان نه د پليتوالے او د بدۍ ګند لرې کړئ، او هغه کلام ډېر په عاجزۍ سره قبول کړئ چې په تاسو کښې کَرلے شوے دے. په دې کښې ستاسو د ژوند بچ کولو طاقت دے او دا تاسو بچ کولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29155, 'James 1:22', 'James', 1, 22, '&nbsp;خو په کلام عمل کوونکى جوړ شئ، او مۀ صرف هغه اورېدونکى جوړېږئ څوک چې ځان دوکه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29156, 'James 1:23', 'James', 1, 23, '&nbsp;ځکه چې هر څوک چې د کلام اورېدونکى دى خو په هغې عمل نۀ کوى نو هغه د هغه سړى په شان دے څوک چې خپل شکل په آئينه کښې ګورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29157, 'James 1:24', 'James', 1, 24, '&nbsp;او خپل ځان ته د کتلو نه وروستو هغه لاړ شى او سمدستى ترې هېر شى چې هغه څنګه ښکارېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29158, 'James 1:25', 'James', 1, 25, '&nbsp;خو کوم سړے چې هغه کامِل شريعت ته په غور سره ګورى چې خلاصون ورکوى او په هغې عمل کوى او څۀ چې هغه واورى هغه هېر نۀ کړى نو په هغې باندې په عمل کولو به هغه برکت حاصل کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29159, 'James 1:26', 'James', 1, 26, '&nbsp;کۀ څوک خپل ځان دينداره ګڼى او بيا خپله ژبه په قابو کښې نۀ ساتى، هغه خپل ځان دوکه کوى، او د هغۀ ديندارى بې‌کاره ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29160, 'James 1:27', 'James', 1, 27, '&nbsp;د خُدائ پلار په وړاندې چې خالص او پاک دين دے يعنې هغه دا چې د يتيمانانو او کونډو په مشکلاتو کښې د هغوئ مدد وکړئ او خپل ځان د دُنيا د ګندګۍ نه وساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29161, 'James 2:1', 'James', 2, 1, '&nbsp;اے زما وروڼو او خوېندو، کۀ چرې ستاسو زمونږ په مالِک عيسىٰ مسيح ايمان وى څوک چې د جلال مالِک دے، نو بيا تاسو څنګه طرفدارى کولے شئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29162, 'James 2:2', 'James', 2, 2, '&nbsp;فرض کړئ چې کۀ يو سړى د سرو زرو ګوته او ښائسته جامې اغوستې وى او ستاسو د عبادت ځائ ته راشى او يو غريب سړے هم په شلېدلو جامو کښې دننه راشى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29163, 'James 2:3', 'James', 2, 3, '&nbsp;کۀ تاسو هغه سړى ته زيات اهميت ورکړئ چې ښائسته جامې يې اچولې وى او ورته ووايئ چې، ”دلته بره د دې عزت په ځائ کښې کښېنئ،“ خو غريب سړى ته ووايئ چې، ”تۀ هلته ودرېږه،“ او يا، ”بهر د ور سره نزدې کښېنه،“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29164, 'James 2:4', 'James', 2, 4, '&nbsp;نو ولې دا تاسو په خپل مينځ کښې طرفدارى ونۀ کړه؟ او تاسو د بدنېتۍ منصفان نۀ شوئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29165, 'James 2:5', 'James', 2, 5, '&nbsp;اے زما خوږو وروڼو او خوېندو، واورئ، ولې خُدائ پاک هغوئ نۀ دى غوره کړى څوک چې د دُنيا په نظر کښې غريب دى چې په ايمان به مالداره شى او د هغه بادشاهۍ وارثان به شى چې مالِک يې د هغوئ سره وعده کړې ده څوک چې ورسره مينه کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29166, 'James 2:6', 'James', 2, 6, '&nbsp;خو تاسو د غريب سپکاوے وکړو. ولې دا مالداره نۀ دے چې په تاسو ظلم کوى او عدالت ته مو راکاږى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29167, 'James 2:7', 'James', 2, 7, '&nbsp;ولې دا هغوئ نۀ دى څوک چې د هغه چا د عزتمند نوم په حقله کُفر غروى په کوم نوم چې تاسو يادېږئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29168, 'James 2:8', 'James', 2, 8, '&nbsp;کۀ په حقيقت کښې تاسو په هغه شاهى شريعت عمل وکړئ چې په کِتاب مقدس کښې دے چې فرمائى چې، ”د خپل ګاونډى سره د خپل ځان په شان مينه کوئ،“ نو تاسو ښۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29169, 'James 2:9', 'James', 2, 9, '&nbsp;خو کۀ چرې تاسو طرفدارى کوئ نو ګناه کوئ او د شريعت په مطابق مجرمان يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29170, 'James 2:10', 'James', 2, 10, '&nbsp;ځکه کۀ يو کس په ټول شريعت عمل کوى او صرف په يوه خبره کښې هم خطا وکړى نو هغه د هغه چا په شان دے چې ټول شريعت ماتوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29171, 'James 2:11', 'James', 2, 11, '&nbsp;ځکه چا چې دا فرمائيلى دى چې، ”زنا مۀ کوئ،“ نو هغۀ دا هم فرمائيلى دى چې، ”قتل مۀ کوئ،“ نو کۀ تاسو زنا ونۀ کړئ او قتل وکړئ نو بيا هم تاسو شريعت مات کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29172, 'James 2:12', 'James', 2, 12, '&nbsp;نو څۀ چې تاسو وايئ او څۀ کوئ خو دا خبره ياده ساتئ چې ستاسو به په هم هغه شريعت اِنصاف کيږى کوم چې تاسو له آزادى درکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29173, 'James 2:13', 'James', 2, 13, '&nbsp;ځکه چا چې رحم ونۀ کړو نو په هغۀ هم د اِنصاف په مطابق رحم نۀ کيږى. بيا هم رحم په اِنصاف غالب دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29174, 'James 2:14', 'James', 2, 14, '&nbsp;اے زما وروڼو او خوېندو، کۀ څوک ووائى چې زۀ ايماندار يم او نېک کارونه نۀ کوى نو د هغۀ د دې ايمان نه څۀ فائده ده؟ ولې داسې ايمان هغۀ له خلاصون ورکولے شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29175, 'James 2:15', 'James', 2, 15, '&nbsp;فرض کړئ کۀ تاسو يو ورور يا خور ووينئ چې خوراک يا جامو ته يې ضرورت وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29176, 'James 2:16', 'James', 2, 16, '&nbsp;او تاسو ورته ووايئ چې، ”په خير لاړ شه، ګرم اوسه او موړ اوسه،“ خو د کومو څيزونو چې هغۀ ته ضرورت وى، هغه ورنۀ کړئ نو د دې فائده څۀ ده؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29177, 'James 2:17', 'James', 2, 17, '&nbsp;دغه شان ايمان هم دے، کۀ د دې سره نيکى کول نۀ وى نو دا ايمان عبث دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29178, 'James 2:18', 'James', 2, 18, '&nbsp;خو څۀ خلق به وائى چې، ”تۀ ايماندار يې او زۀ نېک کارونه کوم.“ تۀ خپل ايمان بغېر د نېک کارونو نه ما ته وښايه او زۀ به خپل ايمان درته په نېک کار کولو وښايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29179, 'James 2:19', 'James', 2, 19, '&nbsp;تۀ په دې خبره يقين کوې چې خُدائ پاک يو دے. دا ډېره ښۀ خبره ده. اګر چې پيريان هم داسې ايمان ساتى او د يرې نه رپيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29180, 'James 2:20', 'James', 2, 20, '&nbsp;اے کم عقله، ولې تۀ په دې هم نۀ پوهېږې چې د نېک کار کولو نه بغېر ايمان عبث دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29181, 'James 2:21', 'James', 2, 21, '&nbsp;نو کله چې زمونږ نيکۀ اِبراهيم خپل زوئ اِسحاق په قربان‌ګاه د قربانۍ په طور پېش کړو نو ولې هغه په دې کار سره صادق نۀ شو څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29182, 'James 2:22', 'James', 2, 22, '&nbsp;نو تا وکتل چې د هغۀ ايمان او عمل په شريکه کار وکړو او د هغۀ دې کار د هغۀ ايمان کامِل کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29183, 'James 2:23', 'James', 2, 23, '&nbsp;او د صحيفو هغه ليکل پوره شو چې فرمائى، ”اِبراهيم په خُدائ پاک ايمان راوړو او دا د هغۀ دپاره په صداقت حساب شو،“ او هغه خليل اللّٰه وبللے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29184, 'James 2:24', 'James', 2, 24, '&nbsp;نو تاسو وينئ چې انسان تش په ايمان نه، بلکې په عمل صادق کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29185, 'James 2:25', 'James', 2, 25, '&nbsp;نو راحب کنجره هم د دې يو بل مثال دے چې هغې په خپل نېک کار سره د خُدائ پاک صداقت حاصل کړو کله چې هغې هغه جاسوسانو له پناه ورکړه او په بله لار يې رُخصت کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29186, 'James 2:26', 'James', 2, 26, '&nbsp;نو څنګه چې بدن بغېر د روح نه مړ دے هم دغه شان ايمان هم بغېر د نېک کار کولو نه مړ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29187, 'James 3:1', 'James', 3, 1, '&nbsp;اے زما وروڼو او خوېندو، په تاسو کښې دې اُستاذان زيات نۀ شى ځکه چې تاسو ته پته ده چې مونږ څوک چې اُستاذان يُو، راسره به لا نور ډېر سخت حساب کِتاب کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29188, 'James 3:2', 'James', 3, 2, '&nbsp;ځکه چې مونږ ټول اکثر غلطيانې کوُو، او څوک چې په خپلو خبرو کښې غلطى نۀ کوى نو هغه کامِل دے او ټول بدن په قابو کښې ساتلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29189, 'James 3:3', 'James', 3, 3, '&nbsp;مونږ د آسونو په خولو کښې د دې دپاره واګې اچوو چې زمونږ په مرضۍ تلل کوى نو دغه شان بيا مونږ د هغوئ پوره بدن هر خوا ته بوتلے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29190, 'James 3:4', 'James', 3, 4, '&nbsp;دغه شان تاسو سمندرى جهازُونو ته وګورئ اګر چې هغه ډېر لوئ وى او په تېزو هواګانو چليږى خو دا د يو ورکوټى پارو په ذريعه د ماڼکى د مرضۍ په مطابق چليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29191, 'James 3:5', 'James', 3, 5, '&nbsp;دغه شان ژبه هم يو ورکوټے اندام دے خو ډيرې غټې خبرې کوى څنګه چې يو ورکوټے بڅرکے يو لوئ ځنګل ته اور لګوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29192, 'James 3:6', 'James', 3, 6, '&nbsp;او ژبه هم اور دے، دا زمونږ په اندامونو کښې د شرارت يوه دُنيا ده، دا په ټول وجود کښې بدى پېدا کوى او زمونږ په ټول ژوندون کښې اور لګوى، او په خپله د دوزخ په اور کښې سوزيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29193, 'James 3:7', 'James', 3, 7, '&nbsp;نو چې هر قِسم ځنګلى ځناور، مارغان، چينجى او کبان د انسان په قابو کښې راتلے شى او راغلى هم دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29194, 'James 3:8', 'James', 3, 8, '&nbsp;خو څوک هم ژبه په قابو کښې نۀ شى راوستلے. دا يوه نا آرامه بلا ده او د وژونکى زهر نه ډکه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29195, 'James 3:9', 'James', 3, 9, '&nbsp;هم په دې ژبه مونږ د مالِک او پلار ثنا وايو، او هم په دې مونږ هغوئ ته چې د خُدائ پاک په صُورت پېدا شوى دى، ښېرې کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29196, 'James 3:10', 'James', 3, 10, '&nbsp;هم د دې يوې خولې نه برکت او هم ښېرې راوځى. اے زما وروڼو او خوېندو، په کار نۀ دى چې داسې وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29197, 'James 3:11', 'James', 3, 11, '&nbsp;ولې د چينې د يوې خولې نه خوږې او ترخې اوبۀ راوځى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29198, 'James 3:12', 'James', 3, 12, '&nbsp;اے زما وروڼو او خوېندو، ولې د اينځر په ونه کښې زيتون، يا په انګور کښې اينځر پېدا کېدے شى څۀ؟ هم دغه شان د ترخې چينې نه خوږې اوبۀ نۀ شى راوتلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29199, 'James 3:13', 'James', 3, 13, '&nbsp;په تاسو کښې څوک هوښيار او پوهه شته دے؟ هغه دې په خپلو کارونو د نېک چال چلن په وسيله او هغه عاجزۍ سره دې دا خبره ثابته کړى، چې د حِکمت نه پېدا کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29200, 'James 3:14', 'James', 3, 14, '&nbsp;خو کۀ ستاسو په خپلو زړُونو کښې سخته کينه او خود غرضى وى، نو فخر پرې مۀ کوئ او مۀ د حق خلاف دروغ وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');